arguments.command:
cd /app; rm -rf /tmp/v; mkdir -p /tmp/v
mk(){ rm -rf /tmp/v/$1; mkdir -p /tmp/v/$1; cp -r shelfmark /tmp/v/$1/; }
fa(){ sed -i 's/if name in cfg.ignore_params:/if name in cfg.ignore_params or name.startswith("utm_"):/' $1/shelfmark/keys.py; }
fb(){ sed -i 's/                return rng/                return loc/' $1/shelfmark/locale.py; }
fc(){ sed -i 's/prefix = f"{route}|{ident}"/prefix = f"{route}|{ident}|"/' $1/shelfmark/cache.py; }
fd(){ sed -i 's/        return int(value)$/        return int(value) * 1000/' $1/shelfmark/config.py; }
for n in A B C D ALL; do mk $n; done
fa /tmp/v/A; fb /tmp/v/B; fc /tmp/v/C; fd /tmp/v/D
for f in fa fb fc fd; do $f /tmp/v/ALL; done
for n in A B C D ALL; do echo $n; python3 tools/replay.py --pkg /tmp/v/$n --since 2027-05-03T11:00:04Z --diff > /tmp/v/$n.out; tail -1 /tmp/v/$n.out; grep -c 'logged=miss replay=hit' /tmp/v/$n.out; done
python3 tools/replay.py --since 2027-05-03T11:00:04Z --diff >/tmp/v/base.out; tail -1 /tmp/v/base.out;grep -c 'logged=miss replay=hit' /tmp/v/base.out

