arguments.command:
cd /app; ls -la shelfmark shelfmark/__pycache__ 2>&1 | head -30; python3 - <<'E'
import re,collections
ids=set(l.split()[0] for l in open('/tmp/v/base.out') if 'logged=hit replay=miss' in l)
c=collections.Counter()
for f in ['logs/access/2027-05-03.log','logs/access/2027-05-04.log']:
    for l in open(f):
        if l.split()[1] in ids:
            m=re.search(r'lang="(.*)"',l); c[m.group(1)]+=1
print(c)
E

